#### Interaction 3: Service-Level Fine-Grained Authorization

```text
1. Microservice receives request from API Gateway
2. Service extracts user context from headers/JWT
3. Service performs endpoint-specific authorization:

   [Authorize(Permission = "claims:approve")]
   public async Task<IActionResult> ApproveClaim(string claimId, decimal approvedAmount)
   {
       var userRoles = User.Claims.Where(c => c.Type == "roles").Select(c => c.Value);
       var claim = await _claimsRepo.GetClaimAsync(claimId);

       // Check 1: Does user have base permission? (already validated by gateway)
       // Check 2: State-level authorization
       if (!userRoles.Contains("CA-Staff") && claim.ServiceState == "CA") {
           return Forbid("User not authorized for California claims");
       }

       // Check 3: Amount-based authorization
       if (approvedAmount > 10000 && !userRoles.Contains("ClaimsSupervisor")) {
           return Forbid("Only supervisors can approve claims over $10K");
       }

       // Check 4: Provider-specific authorization (for ProviderUser role)
       if (userRoles.Contains("ProviderUser")) {
           var userProviderId = User.FindFirst("provider_id")?.Value;
           if (claim.ProviderId != userProviderId) {
               return Forbid("Providers can only approve their own claims");
           }
       }

       // All checks passed - execute business logic
       await _claimsRepo.ApproveClaimAsync(claimId, approvedAmount);
       await _auditLog.LogAsync("ClaimApproved", claimId, User.Identity.Name);

       return Ok(new { status = "approved", claimId, approvedAmount });
   }
```

