#### Variation 2: ASP.NET Core Policy-Based Authorization

**Use Case**: Internal microservices with fine-grained permission requirements

**Implementation**:

```csharp
// Startup.cs - Configure authorization policies
public void ConfigureServices(IServiceCollection services)
{
    services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
        .AddJwtBearer(options =>
        {
            options.Authority = "https://gainwell.okta.com/oauth2/default";
            options.Audience = "api://gainwell-claims-api";
            options.TokenValidationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                RoleClaimType = "roles" // Map JWT roles claim to User.IsInRole()
            };
        });

    services.AddAuthorization(options =>
    {
        // Define policies based on roles
        options.AddPolicy("RequireClaimsProcessor", policy =>
            policy.RequireRole("ClaimsProcessor", "ClaimsSupervisor", "StateAdmin"));

        options.AddPolicy("RequireSupervisor", policy =>
            policy.RequireRole("ClaimsSupervisor", "StateAdmin"));

        options.AddPolicy("RequireStateAdmin", policy =>
            policy.RequireRole("StateAdmin"));

        // Define policies based on custom claims
        options.AddPolicy("RequireCAAccess", policy =>
            policy.RequireAssertion(context =>
                context.User.HasClaim(c => c.Type == "state" && c.Value == "CA") ||
                context.User.IsInRole("StateAdmin")));

        // Define permission-based policies
        options.AddPolicy("CanApproveClaims", policy =>
            policy.Requirements.Add(new PermissionRequirement("claims:approve")));

        options.AddPolicy("CanApproveHighValueClaims", policy =>
            policy.Requirements.Add(new PermissionRequirement("claims:approve:high-value")));
    });

    // Register custom authorization handler
    services.AddSingleton<IAuthorizationHandler, PermissionAuthorizationHandler>();
    services.AddSingleton<IRolePermissionService, RolePermissionService>();
}

// Custom permission requirement
public class PermissionRequirement : IAuthorizationRequirement
{
    public string Permission { get; }

    public PermissionRequirement(string permission)
    {
        Permission = permission;
    }
}

// Custom authorization handler
public class PermissionAuthorizationHandler : AuthorizationHandler<PermissionRequirement>
{
    private readonly IRolePermissionService _rolePermissionService;

    public PermissionAuthorizationHandler(IRolePermissionService rolePermissionService)
    {
        _rolePermissionService = rolePermissionService;
    }

    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        PermissionRequirement requirement)
    {
        // Get user's roles from JWT
        var userRoles = context.User.Claims
            .Where(c => c.Type == "roles")
            .Select(c => c.Value)
            .ToList();

        // Map roles to permissions
        var userPermissions = _rolePermissionService.GetPermissionsForRoles(userRoles);

        // Check if user has required permission
        if (userPermissions.Contains(requirement.Permission))
        {
            context.Succeed(requirement);
        }
        else
        {
            // Check for scoped permissions (e.g., "claims:approve:under-10k" satisfies "claims:approve")
            var matchesScope = userPermissions.Any(p =>
                p.StartsWith(requirement.Permission + ":"));

            if (matchesScope)
            {
                context.Succeed(requirement);
            }
        }

        return Task.CompletedTask;
    }
}

// Controller using authorization policies
[ApiController]
[Route("api/v1/claims")]
[Authorize] // Require authentication for all endpoints
public class ClaimsController : ControllerBase
{
    private readonly IClaimsService _claimsService;
    private readonly IAuditService _auditService;

    [HttpGet]
    [Authorize(Policy = "RequireClaimsProcessor")]
    public async Task<ActionResult<IEnumerable<Claim>>> GetClaims(
        [FromQuery] string state = null,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 50)
    {
        // Additional authorization: Filter by user's state
        var userState = User.FindFirst("state")?.Value;
        if (!User.IsInRole("StateAdmin") && state != null && state != userState)
        {
            return Forbid("User can only view claims from their assigned state");
        }

        var claims = await _claimsService.GetClaimsAsync(state ?? userState, page, pageSize);
        return Ok(claims);
    }

    [HttpGet("{claimId}")]
    [Authorize(Policy = "RequireClaimsProcessor")]
    public async Task<ActionResult<Claim>> GetClaim(string claimId)
    {
        var claim = await _claimsService.GetClaimAsync(claimId);

        if (claim == null)
            return NotFound();

        // Authorization check: User's state matches claim's state
        var userState = User.FindFirst("state")?.Value;
        if (!User.IsInRole("StateAdmin") && claim.ServiceState != userState)
        {
            await _auditService.LogUnauthorizedAccessAttemptAsync(
                User.Identity.Name, claimId, "StateMismatch");
            return Forbid("User not authorized to view claims from other states");
        }

        return Ok(claim);
    }

    [HttpPost("{claimId}/approve")]
    [Authorize(Policy = "CanApproveClaims")]
    public async Task<ActionResult> ApproveClaim(
        string claimId,
        [FromBody] ClaimApprovalRequest request)
    {
        var claim = await _claimsService.GetClaimAsync(claimId);

        if (claim == null)
            return NotFound();

        // Amount-based authorization
        if (request.ApprovedAmount > 10000 &&
            !User.IsInRole("ClaimsSupervisor") &&
            !User.IsInRole("StateAdmin"))
        {
            await _auditService.LogUnauthorizedAccessAttemptAsync(
                User.Identity.Name, claimId, "AmountExceedsAuthorization");
            return Forbid("Only supervisors can approve claims over $10,000");
        }

        await _claimsService.ApproveClaimAsync(claimId, request.ApprovedAmount);
        await _auditService.LogClaimApprovalAsync(User.Identity.Name, claimId, request.ApprovedAmount);

        return Ok(new { status = "approved", claimId, approvedAmount = request.ApprovedAmount });
    }
}
```

