#### Variation 3: Kong Gateway with RBAC Plugin

**Use Case**: Internal service mesh with mTLS authentication and role-based routing

**Implementation**:

```yaml
# Kong Gateway RBAC Configuration
apiVersion: configuration.konghq.com/v1
kind: KongPlugin
metadata:
  name: rbac-authorization
  namespace: gainwell-services
plugin: rbac
config:
  # Enable RBAC enforcement
  enforce: true

  # Role definitions
  roles:
    - name: ClaimsProcessor
      permissions:
        - resource: claims
          actions: [read, create, update]
        - resource: providers
          actions: [read]
        - resource: members
          actions: [read]

    - name: ClaimsSupervisor
      permissions:
        - resource: claims
          actions: [read, create, update, delete, approve]
        - resource: providers
          actions: [read, update]
        - resource: members
          actions: [read]
        - resource: audit-logs
          actions: [read]

    - name: StateAdmin
      permissions:
        - resource: "*"
          actions: ["*"]

  # Extract roles from JWT
  jwt_claim_role: roles

  # Fallback behavior if no roles found
  deny_on_no_roles: true

---
# Apply RBAC to Claims API
apiVersion: configuration.konghq.com/v1
kind: Ingress
metadata:
  name: claims-api
  annotations:
    konghq.com/plugins: rbac-authorization
spec:
  rules:
    - host: claims-api.internal.gainwell.com
      http:
        paths:
          - path: /api/v1/claims
            backend:
              serviceName: claims-service
              servicePort: 8080
```

**Service-Level Role Check (Node.js)**:

```typescript
// Express middleware for role-based authorization
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

interface JWTPayload {
  sub: string;
  roles: string[];
  state?: string;
  provider_id?: string;
}

// Middleware factory for role-based authorization
export function requireRole(...allowedRoles: string[]) {
  return async (req: Request, res: Response, next: NextFunction) => {
    try {
      // Extract JWT from Authorization header
      const authHeader = req.headers.authorization;
      if (!authHeader?.startsWith('Bearer ')) {
        return res.status(401).json({ error: 'Missing or invalid authorization header' });
      }

      const token = authHeader.substring(7);
      const decoded = jwt.decode(token) as JWTPayload;

      if (!decoded || !decoded.roles) {
        return res.status(403).json({
          error: 'insufficient_permissions',
          message: 'No roles found in token'
        });
      }

      // Check if user has any of the allowed roles
      const hasRole = decoded.roles.some(role => allowedRoles.includes(role));

      if (!hasRole) {
        return res.status(403).json({
          error: 'insufficient_permissions',
          message: `User lacks required role. Required: ${allowedRoles.join(', ')}`,
          user_roles: decoded.roles
        });
      }

      // Attach user context to request
      req.user = decoded;
      next();
    } catch (error) {
      return res.status(500).json({ error: 'Authorization check failed' });
    }
  };
}

// Usage in routes
import express from 'express';
const router = express.Router();

// GET /claims - Requires ClaimsProcessor, ClaimsSupervisor, or StateAdmin role
router.get('/claims',
  requireRole('ClaimsProcessor', 'ClaimsSupervisor', 'StateAdmin'),
  async (req, res) => {
    const user = req.user as JWTPayload;

    // Filter claims by user's state (unless StateAdmin)
    const stateFilter = user.roles.includes('StateAdmin')
      ? null
      : user.state;

    const claims = await claimsService.getClaims({ state: stateFilter });
    res.json(claims);
  }
);

// POST /claims/:id/approve - Requires ClaimsSupervisor or StateAdmin
router.post('/claims/:id/approve',
  requireRole('ClaimsSupervisor', 'StateAdmin'),
  async (req, res) => {
    const { id } = req.params;
    const { approvedAmount } = req.body;
    const user = req.user as JWTPayload;

    const claim = await claimsService.getClaim(id);

    if (!claim) {
      return res.status(404).json({ error: 'Claim not found' });
    }

    // State-level authorization
    if (!user.roles.includes('StateAdmin') && claim.serviceState !== user.state) {
      await auditService.logUnauthorizedAccess(user.sub, id, 'StateMismatch');
      return res.status(403).json({
        error: 'User not authorized for claims from other states'
      });
    }

    await claimsService.approveClaim(id, approvedAmount);
    await auditService.logClaimApproval(user.sub, id, approvedAmount);

    res.json({ status: 'approved', claimId: id, approvedAmount });
  }
);

export default router;
```

